package org.localvoice.tts;

import java.io.*;
import java.nio.file.*;
import java.util.*;

/** Production download-only resolver, real host paths. No Android no-follow claim. */
public final class DownloadPathsCheck {
    @org.junit.Test public void check() throws Exception { main(new String[0]); }
    interface Action {void run()throws Exception;}
    static int passed,skipped;
    static final class Skip extends Exception {Skip(String why){super(why);}}
    static void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    static void rejects(Action action)throws Exception{try{action.run();throw new AssertionError("Expected IOException");}catch(IOException expected){}}
    static void test(String name,Action action)throws Exception{try{action.run();passed++;System.out.println("PASS "+name);}catch(Skip skip){skipped++;System.out.println("SKIP "+name+": "+skip.getMessage());}}
    static final class Fixture implements AutoCloseable {
        final File root,models,stage;final ModelFiles.DownloadPaths paths;
        Fixture()throws IOException{root=Files.createTempDirectory("localvoice-download-paths-").toFile();models=new File(root,"models");stage=new File(models,"model.download");check(stage.mkdirs(),"private stage fixture");paths=new ModelFiles.DownloadPaths(models,stage);}
        public void close()throws IOException{Path boundary=root.toPath().toAbsolutePath().normalize();try(java.util.stream.Stream<Path> walk=Files.walk(boundary)){for(Path p:(Iterable<Path>)walk.sorted(Comparator.reverseOrder())::iterator){check(p.toAbsolutePath().normalize().startsWith(boundary),"cleanup remains private");Files.deleteIfExists(p);}}}
    }
    public static void main(String[] args)throws Exception{
        test("planning validates relative grammar without canonical or metadata work",()->{try(Fixture f=new Fixture()){File anchor=f.stage.getCanonicalFile();StorageMetrics.start();for(int i=0;i<500;i++)check(f.paths.plan("nested/file"+i).equals(new File(anchor,"nested/file"+i)),"stable owned plan");check(StorageMetrics.FILE_STATS.value.get()==0&&StorageMetrics.CANONICAL_CALLS.value.get()==0,"lookup has no filesystem work");StorageMetrics.finish();check(!new File(f.stage,"nested").exists(),"planning does not create directories");}});
        test("absolute traversal backslash drive empty and dot paths reject",()->{try(Fixture f=new Fixture()){for(String invalid:new String[]{"","/root","../escape","a/../b","a/./b","a//b","a/","C:/file","a\\b"})rejects(()->f.paths.plan(invalid));}});
        test("checked missing path fails without creating parents",()->{try(Fixture f=new Fixture()){rejects(()->f.paths.checked("missing/nested/file"));check(!new File(f.stage,"missing").exists(),"checked is not a directory creator");}});
        test("write preparation creates controlled parents and checked requires regular leaf",()->{try(Fixture f=new Fixture()){File leaf=f.paths.prepareWrite("nested/deeper/file");check(leaf.getParentFile().isDirectory()&&!leaf.exists(),"only missing parents created");rejects(()->f.paths.checked("nested/deeper/file"));Files.write(leaf.toPath(),new byte[]{1,2,3});check(f.paths.checked("nested/deeper/file").equals(leaf),"regular leaf checked with stable key");}});
        test("existing regular leaf remains unchanged for caller replacement policy",()->{try(Fixture f=new Fixture()){File leaf=f.paths.prepareWrite("file");Files.write(leaf.toPath(),new byte[]{7});check(f.paths.prepareWrite("file").equals(leaf)&&Arrays.equals(Files.readAllBytes(leaf.toPath()),new byte[]{7}),"resolver never deletes or overwrites a leaf");}});
        test("nondirectory parent fails closed at write and checked boundaries",()->{try(Fixture f=new Fixture()){File parent=new File(f.stage,"parent");Files.write(parent.toPath(),new byte[]{9});rejects(()->f.paths.prepareWrite("parent/file"));rejects(()->f.paths.checked("parent/file"));check(Arrays.equals(Files.readAllBytes(parent.toPath()),new byte[]{9}),"blocking file preserved");}});
        test("directory at expected leaf fails rather than accepting model bytes",()->{try(Fixture f=new Fixture()){check(new File(f.stage,"leaf").mkdir(),"directory leaf");rejects(()->f.paths.prepareWrite("leaf"));rejects(()->f.paths.checked("leaf"));}});
        test("late parent replacement is rechecked at final hash boundary",()->{try(Fixture f=new Fixture()){File leaf=f.paths.prepareWrite("parent/file");Files.write(leaf.toPath(),new byte[]{1});f.paths.checked("parent/file");check(leaf.delete()&&leaf.getParentFile().delete(),"remove only fixture parents");Files.write(new File(f.stage,"parent").toPath(),new byte[]{3});rejects(()->f.paths.checked("parent/file"));}});
        test("late leaf type change is rechecked at final barrier",()->{try(Fixture f=new Fixture()){File leaf=f.paths.prepareWrite("leaf");Files.write(leaf.toPath(),new byte[]{1});f.paths.checked("leaf");check(leaf.delete()&&leaf.mkdir(),"replace private leaf with directory");rejects(()->f.paths.checked("leaf"));}});
        test("outside staging and absent staging cannot initialize a transaction",()->{try(Fixture f=new Fixture()){File outside=new File(f.root,"outside");check(outside.mkdir(),"outside sibling fixture");rejects(()->new ModelFiles.DownloadPaths(f.models,outside));rejects(()->new ModelFiles.DownloadPaths(f.models,new File(f.models,"absent")));}});
        test("Windows short root alias resolves to stable keys without perlookup canonical calls",()->{try(Fixture f=new Fixture()){File canonicalStage=f.stage.getCanonicalFile();StorageMetrics.start();for(int i=0;i<50;i++)check(f.paths.plan("file").equals(new File(canonicalStage,"file")),"short alias has canonical stable key");check(StorageMetrics.CANONICAL_CALLS.value.get()==0,"canonicalization limited to constructor");StorageMetrics.finish();}});
        test("root staging leaf and internal or external ancestor links reject",()->{try(Fixture f=new Fixture()){Path leaf=new File(f.stage,"link").toPath();File target=new File(f.root,"outside-file");Files.write(target.toPath(),new byte[]{4});try{Files.createSymbolicLink(leaf,target.toPath());}catch(UnsupportedOperationException|FileSystemException unavailable){throw new Skip("host cannot create links; actual Android root/leaf/ancestor gates required");}rejects(()->f.paths.prepareWrite("link"));rejects(()->f.paths.checked("link"));Path ancestor=new File(f.stage,"ancestor").toPath();Files.createSymbolicLink(ancestor,f.root.toPath());rejects(()->f.paths.prepareWrite("ancestor/new-file"));rejects(()->f.paths.checked("ancestor/outside-file"));Path internal=new File(f.stage,"internal").toPath();Files.createSymbolicLink(internal,f.stage.toPath());rejects(()->f.paths.prepareWrite("internal/new-file"));Path rootLink=new File(f.root,"models-link").toPath();Files.createSymbolicLink(rootLink,f.models.toPath());rejects(()->new ModelFiles.DownloadPaths(rootLink.toFile(),rootLink.resolve("model.download").toFile()));Path stageLink=new File(f.models,"stage-link").toPath();Files.createSymbolicLink(stageLink,f.stage.toPath());rejects(()->new ModelFiles.DownloadPaths(f.models,stageLink.toFile()));check(!new File(f.root,"new-file").exists()&&Arrays.equals(Files.readAllBytes(target.toPath()),new byte[]{4}),"nothing outside stage changed");}});
        System.out.println("Download path checks: "+passed+" PASS, "+skipped+" SKIP; host path checks are not Android O_NOFOLLOW evidence");
    }
}
